// Customer app gate (r39), SERVER ONLY. Fail closed: the switch (CYRUS_CUSTOMER_APP=1) AND the studio viewer gate
// (preview accounts until the studios open) must both say yes, else the route 404s as if it did not exist.
// Every page and every server action calls appViewer() itself; nothing trusts the layout alone.
import { notFound } from "next/navigation";
import type { User } from "@prisma/client";
import { onCyrusHost } from "@/lib/auth";
import { bridgeConfig } from "@/lib/cyrus/bridge/config";
import { studioViewer } from "@/lib/cyrus/studios/deps";
import { customerAppEnabled, appHref, APP_BASE } from "@/lib/cyrus/app/flags";

export type AppViewer = { user: User; onCyrus: boolean; nxeon: string; href: (internalPath: string) => string };

export async function appViewerOrNull(): Promise<AppViewer | null> {
  if (!customerAppEnabled()) return null;
  const v = await studioViewer().catch(() => null);
  if (!v) return null;
  const onCyrus = await onCyrusHost();
  return { user: v.user, onCyrus, nxeon: bridgeConfig().nxeonOrigin, href: (p) => appHref(p, onCyrus) };
}

export async function appViewer(): Promise<AppViewer> {
  const v = await appViewerOrNull();
  if (!v) notFound();
  return v;
}

export const P = {
  home: APP_BASE, new: `${APP_BASE}/new`, projects: `${APP_BASE}/projects`, account: `${APP_BASE}/account`,
  project: (rootId: string) => `${APP_BASE}/projects/${encodeURIComponent(rootId)}`,
};
/** The existing studio pages (same on both hosts: /dashboard/cyrus passes through on cyrus.my). */
export const studioHref = (buildId?: string | null, studio?: string) =>
  !buildId ? "/dashboard/cyrus" : studio ? `/dashboard/cyrus/${encodeURIComponent(buildId)}/studio/${studio}` : `/dashboard/cyrus/${encodeURIComponent(buildId)}`;
// Cyrus customer app (r39): the switch. OFF unless CYRUS_CUSTOMER_APP=1; even then every page also needs the
// studio viewer gate (preview accounts until the studios go public). Pure: no host, no Nxeon imports.
export const CUSTOMER_APP_FLAG = "CYRUS_CUSTOMER_APP";

export const customerAppEnabled = (env: Record<string, string | undefined> = process.env) => env[CUSTOMER_APP_FLAG] === "1";

/** Public paths on the Cyrus host (cyrus.my) -> the app's internal tree. Used by the dual-host routing. */
export const APP_BASE = "/dashboard/cyrus/app";
export const CYRUS_APP_PATHS: Record<string, string> = {
  "/home": APP_BASE,
  "/new": `${APP_BASE}/new`,
  "/account": `${APP_BASE}/account`,
  "/projects": `${APP_BASE}/projects`,
};

/** cyrus.my public path for an internal app path (identity elsewhere): used for links that must work on both hosts. */
export function appHref(path: string, onCyrusHost: boolean): string {
  if (!onCyrusHost || !path.startsWith(APP_BASE)) return path;
  const rest = path.slice(APP_BASE.length);
  if (rest === "" || rest.startsWith("?")) return "/home" + rest;
  return rest;
}
