// Cyrus notification copy + email templates (r40). PURE, client-safe. One function per event builds the in-app title /
// body / link and the email (subject, HTML, plain text) from the event's data only (no invented figures).
// Visual language: the cyrus.my landing (near-black #050508, white type, electric blue #3d7bff -> violet #8b5cff
// accents), table layout + inline styles so it renders in every mail client, dark by design.
import type { NotifyEvent } from "./events";

const STUDIO = "/dashboard/cyrus"; // CYRUS_STUDIO_PATH (lib/cyrus/public-gate.ts); cyrus.my serves the same app

export type Rendered = { title: string; body: string; href: string | null; subject: string; html: string; text: string };
export type RenderCtx = { appBase: string; prefsUrl: string };

const esc = (s: unknown) => String(s ?? "").replace(/[&<>"']/g, (c) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" })[c]!);
const str = (d: Record<string, unknown>, k: string, max = 120) => String(d[k] ?? "").replace(/[\r\n]+/g, " ").slice(0, max);
const safeHref = (base: string, path: string) => (/^\/[A-Za-z0-9/_?=&.%-]*$/.test(path) ? `${base.replace(/\/$/, "")}${path}` : base);

function copy(ev: NotifyEvent, d: Record<string, unknown>): { title: string; body: string; path: string | null; cta: string } {
  const name = str(d, "name") || "your mod";
  switch (ev) {
    case "build.finished": {
      const ok = d.status === "succeeded";
      return { title: ok ? `${name} is built` : `${name} did not build`, body: ok ? "Your build finished. Test it, install it on a server, or keep changing it." : `The build stopped${str(d, "reason") ? `: ${str(d, "reason", 200)}` : "."} The build page shows what happened and what was charged.`, path: d.buildId ? `${STUDIO}/${encodeURIComponent(str(d, "buildId", 64))}` : STUDIO, cta: ok ? "Open the build" : "See what happened" };
    }
    case "install.result": {
      const ok = d.ok === true;
      return { title: ok ? `${name} is on ${str(d, "server") || "your server"}` : `${name} was not installed`, body: ok ? (d.restartRequired ? "Installed. Restart the server to load it." : "Installed and loaded.") : `Nothing changed on the server${str(d, "reason") ? `: ${str(d, "reason", 200)}` : "."} Any partial change was rolled back.`, path: STUDIO, cta: "Open Cyrus" };
    }
    case "mod.outdated":
      return { title: `${name} may need a rebuild`, body: `${str(d, "game") || "The game"} ${str(d, "version") ? `moved to ${str(d, "version")}` : "was updated"}. Your mod was built for ${str(d, "builtFor") || "an older version"}; rebuild it to keep it working.`, path: d.buildId ? `${STUDIO}/${encodeURIComponent(str(d, "buildId", 64))}` : STUDIO, cta: "Rebuild" };
    case "takedown":
      return { title: `${name} was taken down`, body: `${str(d, "what") || "Content"} was removed${str(d, "reason") ? ` (${str(d, "reason", 200)})` : ""}. ${d.counterNotice ? "If you believe this is a mistake you can send a counter-notice by replying to this email." : "Projects that used it keep their own copy and keep working."}`, path: STUDIO, cta: "Open Cyrus" };
    case "tokens.low":
      return { title: "Your Cyrus tokens are running low", body: `${str(d, "available") ? `${str(d, "available")} tokens left.` : "Your balance is low."} Top up or change plan to keep building.`, path: STUDIO, cta: "Get tokens" };
  }
}

export function renderNotification(ev: NotifyEvent, data: Record<string, unknown>, ctx: RenderCtx): Rendered {
  const c = copy(ev, data);
  const href = c.path ? safeHref(ctx.appBase, c.path) : null;
  const subject = c.title.slice(0, 120);
  const text = `${c.title}\n\n${c.body}\n\n${href ? `${c.cta}: ${href}\n\n` : ""}Notification settings: ${ctx.prefsUrl}\nCyrus, a Nxeon product.`;
  const html = `<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width"><meta name="color-scheme" content="dark"><title>${esc(subject)}</title></head>
<body style="margin:0;padding:0;background:#050508;color:#ffffff;font-family:Inter,Segoe UI,Helvetica,Arial,sans-serif;">
<table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="background:#050508;"><tr><td align="center" style="padding:32px 16px;">
<table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="max-width:560px;">
<tr><td style="padding:0 0 20px 0;font-size:18px;font-weight:700;letter-spacing:.08em;color:#ffffff;">CYRUS</td></tr>
<tr><td style="height:3px;background:#3d7bff;background-image:linear-gradient(90deg,#3d7bff,#8b5cff);font-size:0;line-height:0;">&nbsp;</td></tr>
<tr><td style="padding:28px 0 8px 0;font-size:22px;line-height:1.3;font-weight:700;color:#ffffff;">${esc(c.title)}</td></tr>
<tr><td style="padding:0 0 24px 0;font-size:15px;line-height:1.6;color:#cfd3e0;">${esc(c.body)}</td></tr>
${href ? `<tr><td style="padding:0 0 32px 0;"><a href="${esc(href)}" style="display:inline-block;padding:12px 20px;border-radius:10px;background:#3d7bff;background-image:linear-gradient(90deg,#3d7bff,#8b5cff);color:#ffffff;text-decoration:none;font-weight:600;font-size:14px;">${esc(c.cta)}</a></td></tr>` : ""}
<tr><td style="border-top:1px solid #1c1d2b;padding:16px 0 0 0;font-size:12px;line-height:1.6;color:#8a8fa3;">You get this because of your <a href="${esc(ctx.prefsUrl)}" style="color:#9cc0ff;">Cyrus notification settings</a>.<br>Cyrus, a Nxeon product.</td></tr>
</table></td></tr></table></body></html>`;
  return { title: c.title.slice(0, 160), body: c.body.slice(0, 500), href, subject, html, text };
}

