import type { CyrusGame } from "@/lib/cyrus/games";
import type { CyrusModelId } from "@/lib/cyrus/models";
import { CYRUS_MODELS } from "@/lib/cyrus/models";
import { estimate } from "@/lib/cyrus/estimate";
import { CYRUS_TEMPLATES, CYRUS_TEMPLATE_CATS } from "@/lib/cyrus/templates";
import type { MbServer } from "@/lib/cyrus/builder/types";
import { cyrusTokens } from "@/components/cyrus-tokens/store";

export type CostInfo = { active: boolean; enforce: boolean; available: number; models: CyrusModelId[]; reserve: Record<string, Record<string, [number, number]>> | null };

const n = (x: number) => x.toLocaleString("en-US");

export function NewModFlow({ games, servers, cost, projectBase, studioHref }: { games: CyrusGame[]; servers: MbServer[]; cost: CostInfo; projectBase: string; studioHref: string }) {
  const live = games.filter((g) => g.status === "live");
  const [gameId, setGameId] = useState(live[0]?.id ?? "");
  const game = games.find((g) => g.id === gameId) ?? live[0];
  const [version, setVersion] = useState(game?.defaultVersion ?? game?.versions[0] ?? "");
  const [serverId, setServerId] = useState<string>("");
  const [model, setModel] = useState<CyrusModelId>(cost.active && cost.models.length ? (cost.models.includes("saka") ? "saka" : cost.models[0]) : "saka");
  const [cat, setCat] = useState<(typeof CYRUS_TEMPLATE_CATS)[number]>("All");
  const [prompt, setPrompt] = useState("");
  const [busy, setBusy] = useState(false);
  const [err, setErr] = useState<string | null>(null);

  const est = useMemo(() => (prompt.trim() ? estimate(prompt, model) : null), [prompt, model]);
  const table = cost.active && cost.reserve ? cost.reserve[model] : null;
  const range = est && table ? table[est.complexity] : null;
  const span = table ? [Math.min(...Object.values(table).map((r) => r[0])), Math.max(...Object.values(table).map((r) => r[1]))] : null;
  const locked = cost.active && cost.enforce && !cost.models.includes(model);
  const short = !!range && cost.enforce && cost.available < range[0];
  const templates = CYRUS_TEMPLATES.filter((t) => cat === "All" || t.cat === cat);
  const step = !game ? 1 : !prompt.trim() ? 3 : 4;

  const create = async () => {
    setBusy(true); setErr(null);
    try {
      const r = await fetch("/api/mod-builder/builds", { method: "POST", headers: { "content-type": "application/json" }, body: JSON.stringify({ prompt: prompt.trim(), mcVersion: version, model }) });
      const j = (await r.json().catch(() => ({}))) as { build?: { id: string; rootBuildId: string | null }; error?: string; code?: string };
      if (r.status === 201 && j.build) { location.href = `${projectBase}/${encodeURIComponent(j.build.rootBuildId || j.build.id)}${serverId ? `?server=${encodeURIComponent(serverId)}` : ""}`; return; }
      if (cyrusTokens.handleBuildError(j)) setErr(j.error || "Not enough tokens for this build.");
      else setErr(j.error || `Could not start the build (${r.status}).`);
    } catch { setErr("Network error. Nothing was started."); }
    setBusy(false);
  };

  return (
    <div className="cx-grid" style={{ alignItems: "start" }}>
      <div className="cx-s8" style={{ display: "grid", gap: 14 }}>
        <ol className="cx-steps" aria-label="Steps" style={{ listStyle: "none", padding: 0, margin: 0 }}>
          {["Game", "Version and server", "Describe", "Build"].map((s, i) => <li key={s} className="cx-step" data-on={step >= i + 1 ? "1" : "0"}><i>{i + 1}</i>{s}</li>)}
        </ol>

        <section className="cx-card" aria-labelledby="nm-game">
          <div className="cx-card-h"><h2 className="cx-h2" id="nm-game">Game</h2></div>
          <div className="cx-pick" role="radiogroup" aria-label="Game">
            {games.map((g) => (
              <button key={g.id} type="button" role="radio" aria-checked={g.id === gameId} className="cx-opt" disabled={g.status !== "live"} onClick={() => { setGameId(g.id); setVersion(g.defaultVersion ?? g.versions[0] ?? ""); }}>
                <span style={{ display: "flex", alignItems: "center", gap: 10 }}><span className={`cx-tile${g.id === gameId ? " cx-energy" : ""}`}>{g.mark}</span><span className="cx-t">{g.name}</span></span>
                <span className="cx-d">{g.status === "live" ? g.builds : "Coming soon"}</span>
              </button>
            ))}
          </div>
        </section>

        <section className="cx-card" aria-labelledby="nm-target">
          <div className="cx-card-h"><h2 className="cx-h2" id="nm-target">Version and server</h2></div>
          <div className="cx-grid">
            <label className="cx-label cx-s6">{game?.loader ?? "Server"} version
              <select className="cx-select" value={version} onChange={(e) => setVersion(e.target.value)}>
                {(game?.versions ?? []).map((x) => <option key={x} value={x}>{game?.name} {x}</option>)}
              </select>
            </label>
            <label className="cx-label cx-s6">Install on
              <select className="cx-select" value={serverId} onChange={(e) => setServerId(e.target.value)}>
                <option value="">No server: I will download the jar</option>
                {servers.map((s) => <option key={s.id} value={s.id} disabled={!s.compatible}>{s.name}{s.compatible ? "" : ` (${s.reason ?? "not ready"})`}</option>)}
              </select>
            </label>
          </div>
          <p className="cx-faint" style={{ margin: "10px 0 0", fontSize: 12.5 }}>{servers.length ? "You install from the project page once the build and its Test Flight finish." : "No Minecraft servers on your Nxeon account: you get a jar to install anywhere."}</p>
        </section>

        <section className="cx-card" aria-labelledby="nm-tpl">
          <div className="cx-card-h"><h2 className="cx-h2" id="nm-tpl">Start from a template</h2><span className="cx-aside">or write your own below</span></div>
          <div className="cx-seg" role="group" aria-label="Template category" style={{ marginBottom: 12 }}>
            {CYRUS_TEMPLATE_CATS.map((c) => <button key={c} type="button" aria-pressed={c === cat} onClick={() => setCat(c)}>{c}</button>)}
          </div>
          <div className="cx-pick">
            {templates.map((t) => (
              <button key={t.id} type="button" className="cx-opt" aria-pressed={prompt === t.prompt} onClick={() => { setPrompt(t.prompt); if (!cost.active || cost.models.includes(t.model)) setModel(t.model); }}>
                <span className="cx-eyebrow">{t.cat}</span><span className="cx-t">{t.title}</span><span className="cx-d">{t.blurb}</span>
              </button>
            ))}
          </div>
        </section>

        <section className="cx-card" aria-labelledby="nm-desc">
          <div className="cx-card-h"><h2 className="cx-h2" id="nm-desc">Describe your mod</h2></div>
          <textarea className="cx-textarea" aria-labelledby="nm-desc" value={prompt} onChange={(e) => setPrompt(e.target.value)} maxLength={6000} rows={6} placeholder="A /bounty command: players put a price on someone, whoever gets the kill collects it. Show active bounties in a menu." />
          <div style={{ display: "grid", gridTemplateColumns: "repeat(auto-fill, minmax(170px, 1fr))", gap: 10, marginTop: 12 }} role="radiogroup" aria-label="Model">
            {CYRUS_MODELS.map((m) => {
              const off = cost.active && cost.enforce && !cost.models.includes(m.id);
              return (
                <button key={m.id} type="button" role="radio" aria-checked={m.id === model} className="cx-opt" onClick={() => setModel(m.id)}>
                  <span className="cx-t">{m.name}{off ? " · locked" : ""}{est?.recommended === m.id ? <span className="cx-pill cx-ok" style={{ marginLeft: 8 }}>fits</span> : null}</span>
                  <span className="cx-d">{m.bestFor}</span>
                </button>
              );
            })}
          </div>
          <p className="cx-faint" style={{ margin: "10px 0 0", fontSize: 12.5 }}>Prefer the full studio (attachments, assets, chat)? <a href={studioHref} style={{ textDecoration: "underline" }}>Open the studio</a>.</p>
        </section>
      </div>

      <aside className="cx-cost cx-cost-col" aria-label="Cost">
        <section className="cx-card" style={{ display: "grid", gap: 12 }}>
          <div className="cx-eyebrow">Cost</div>
          {cost.active && table ? (
            <>
              <div className="cx-big">{range ? `${n(range[0])}–${n(range[1])}` : span ? `${n(span[0])}–${n(span[1])}` : "—"}<span className="cx-muted" style={{ fontSize: 14, fontWeight: 500 }}> tokens</span></div>
              <p className="cx-muted" style={{ margin: 0, fontSize: 13 }}>{range ? `${est!.complexity[0].toUpperCase()}${est!.complexity.slice(1)} mod on ${CYRUS_MODELS.find((m) => m.id === model)?.name}: the build holds up to ${n(range[1])} while it runs and spends only what it uses. A failed build gives them back.` : `What a ${CYRUS_MODELS.find((m) => m.id === model)?.name} build can hold, simpl
              <div className="cx-list">
                <div className="cx-row"><span className="cx-grow cx-muted">Available</span><b>{n(cost.available)}</b></div>
                {est ? <div className="cx-row"><span className="cx-grow cx-muted">Time</span><span>about {est.minutes[0]}–{est.minutes[1]} min</span></div> : null}
              </div>
              {locked ? <p className="cx-error" style={{ margin: 0 }}>Your plan does not include this model.</p> : short ? <p className="cx-error" style={{ margin: 0 }}>Not enough tokens for this build.</p> : null}
              {locked || short ? <button type="button" className="cx-btn cx-btn-sm" onClick={() => cyrusTokens.open({ reason: locked ? "model_locked" : "insufficient_tokens" })}>{locked ? "See plans" : "Get tokens"}</button> : null}
            </>
          ) : (
            <p className="cx-muted" style={{ margin: 0, fontSize: 13 }}>Tokens are not active on this account yet, so this build follows the preview rules. {est ? `About ${est.minutes[0]}–${est.minutes[1]} min.` : ""}</p>
          )}
          <button type="button" className="cx-btn cx-btn-energy" disabled={busy || !prompt.trim() || !version || locked || short} onClick={create} data-tour="build">{busy ? "Starting…" : "Build mod"}</button>
          {err ? <p className="cx-error" role="alert" style={{ margin: 0 }}>{err}</p> : null}
          <p className="cx-faint" style={{ margin: 0, fontSize: 12 }}>Every build passes a safety scan. When Test Flight runs, its result shows on the project page before you install.</p>
        </section>
      </aside>
    </div>
  );
}
