"use client";
// Onboarding tour (r39): a short spotlight walk over the dashboard, shown once per browser (localStorage is only a
// convenience here; it can fail and the tour then simply shows again). Esc or "Skip" ends it; "Take the tour" in
// the account page restarts it (?tour=1).
import { useCallback, useEffect, useState } from "react";
import { createPortal } from "react-dom";

const STEPS = [
  { sel: '[data-tour="new"]', title: "Start a mod", body: "Pick the game, version and server, see the cost first, then describe what you want or start from a template." },
  { sel: '[data-tour="projects"]', title: "Your projects", body: "Every mod is a project: its builds, revisions, Test Flight results and installs, with rollback to any earlier version." },
  { sel: '[data-tour="tokens"]', title: "Plan and tokens", body: "Builds spend tokens. The estimate is always shown before you build, and top-ups go through Nxeon checkout." },
  { sel: '[data-tour="servers"]', title: "Your servers", body: "Minecraft servers on your Nxeon account. Ready ones can take an install straight from a project." },
  { sel: '[data-tour="nav-account"]', title: "Account", body: "API keys, notifications, connected servers, billing, and your data." },
] as const;
const KEY = "cyrus-app-tour-v1";

export function Tour() {
  const [i, setI] = useState(-1);
  const [box, setBox] = useState<DOMRect | null>(null);
  useEffect(() => {
    let seen = false;
    try { seen = localStorage.getItem(KEY) === "done"; } catch { /* private mode: show it */ }
    if (new URLSearchParams(location.search).get("tour") === "1") seen = false;
    if (!seen) setI(0);
  }, []);
  const end = useCallback(() => { setI(-1); try { localStorage.setItem(KEY, "done"); } catch { /* ignore */ } }, []);
  useEffect(() => {
    if (i < 0) return;
    const place = () => {
      const el = [...document.querySelectorAll<HTMLElement>(STEPS[i].sel)].find((e) => e.offsetParent !== null);
      if (!el) { if (i < STEPS.length - 1) setI(i + 1); else end(); return; }
      el.scrollIntoView({ block: "nearest", behavior: matchMedia("(prefers-reduced-motion: reduce)").matches ? "auto" : "smooth" });
      setBox(el.getBoundingClientRect());
    };
    place(); const t = setTimeout(place, 350);
    const onKey = (e: KeyboardEvent) => { if (e.key === "Escape") end(); };
    addEventListener("resize", place); addEventListener("scroll", place, true); addEventListener("keydown", onKey);
    return () => { clearTimeout(t); removeEventListener("resize", place); removeEventListener("scroll", place, true); removeEventListener("keydown", onKey); };
  }, [i, end]);
  if (i < 0 || !box) return null;
  const s = STEPS[i], pad = 6;
  const below = box.bottom + 190 < innerHeight;
  const left = Math.max(12, Math.min(innerWidth - 332, box.left));
  // portalled to <body>: portal frames may transform their content, which would offset position:fixed
  return createPortal(
    <div className="cx-app cx-tour-root">
      <div className="cx-tour-ring" style={{ left: box.left - pad, top: box.top - pad, width: box.width + pad * 2, height: box.height + pad * 2 }} />
      <div className="cx-tour" role="dialog" aria-modal="false" aria-labelledby="cx-tour-t" style={{ left, top: below ? box.bottom + 14 : Math.max(12, box.top - 186) }}>
        <div className="cx-eyebrow">Step {i + 1} of {STEPS.length}</div>
        <h3 id="cx-tour-t" className="cx-h2" style={{ margin: "6px 0" }}>{s.title}</h3>
        <p className="cx-muted" style={{ margin: 0, fontSize: 13.5 }}>{s.body}</p>
        <div style={{ display: "flex", gap: 8, marginTop: 14, justifyContent: "flex-end" }}>
          <button type="button" className="cx-btn cx-btn-sm" onClick={end}>Skip</button>
          {i > 0 ? <button type="button" className="cx-btn cx-btn-sm" onClick={() => setI(i - 1)}>Back</button> : null}
          <button type="button" className="cx-btn cx-btn-pri cx-btn-sm" onClick={() => (i < STEPS.length - 1 ? setI(i + 1) : end())} autoFocus>{i < STEPS.length - 1 ? "Next" : "Done"}</button>
        </div>
      </div>
    </div>,
    document.body,
  );
}
