      case "help": return <a key={i} href={`${base}/${n.slug}`}><In c={n.c} base={base} /></a>;
      case "link": return <a key={i} href={n.href} {...(/^https?:/.test(n.href) ? { rel: "noreferrer noopener", target: "_blank" } : {})}><In c={n.c} base={base} /></a>;
    }
  })}</>;
}

export function HelpBody({ blocks, base }: { blocks: Block[]; base: string }) {
  return (
    <div className="hp-body">
      {blocks.map((b, i) => {
        switch (b.t) {
          case "h": return b.level === 2 ? <h2 key={i} id={b.id}><In c={b.c} base={base} /></h2> : <h3 key={i} id={b.id}><In c={b.c} base={base} /></h3>;
          case "p": return <p key={i}><In c={b.c} base={base} /></p>;
          case "ul": return <ul key={i}>{b.items.map((it, j) => <li key={j}><In c={it} base={base} /></li>)}</ul>;
          case "ol": return <ol key={i}>{b.items.map((it, j) => <li key={j}><In c={it} base={base} /></li>)}</ol>;
          case "quote": return <blockquote key={i} className="hp-note"><In c={b.c} base={base} /></blockquote>;
          case "code": return <pre key={i} className="hp-pre"><code>{b.v}</code></pre>;
          case "table": return (
            <div key={i} className="hp-tablewrap"><table className="hp-table"><thead><tr>{b.head.map((h, j) => <th key={j}><In c={h} base={base} /></th>)}</tr></thead>
              <tbody>{b.rows.map((r, j) => <tr key={j}>{r.map((c, k) => <td key={k}><In c={c} base={base} /></td>)}</tr>)}</tbody></table></div>
