import type { Metadata } from "next";
import { helpArticles, helpIndex } from "@/lib/cyrus/help/articles.server";
import { HELP_CATEGORIES, searchHelp } from "@/lib/cyrus/help/search";
import { helpGate } from "./_gate";

export const dynamic = "force-dynamic";
export const metadata: Metadata = { title: "Cyrus Help", description: "Guides for building, testing and installing Minecraft mods with Cyrus." };

export default async function HelpHome({ searchParams }: { searchParams: Promise<{ q?: string }> }) {
  const { base } = await helpGate();
  const q = String((await searchParams).q ?? "").slice(0, 80).trim();
  const results = q ? searchHelp(helpIndex(), q) : [];
  const all = helpArticles();
  return (
    <>
      <div className="hp-hero">
        <div className="cx-eyebrow">Cyrus Help</div>
        <h1>How can we help?</h1>
        <form className="hp-search" action={base} role="search">
          <input type="search" name="q" defaultValue={q} placeholder="Search: tokens, install, Test Flight…" aria-label="Search help" autoComplete="off" />
          <button className="cx-btn cx-btn-pri" type="submit">Search</button>
        </form>
      </div>
      {q ? (
        <section className="hp-results" aria-label="Search results">
          <p className="cx-muted">{results.length ? `${results.length} article${results.length === 1 ? "" : "s"} for “${q}”` : `Nothing found for “${q}”. Try a shorter word, or browse below.`}</p>
          {results.map((r) => <a key={r.slug} className="hp-row" href={`${base}/${r.slug}`}><b>{r.title}</b><span>{r.summary}</span></a>)}
        </section>
      ) : null}
      <div className="hp-cats">
        {HELP_CATEGORIES.map((c) => {
          const list = all.filter((a) => a.category === c);
          return list.length ? (
            <section key={c} className="cx-card hp-cat" aria-label={c}>
              <h2>{c}</h2>
              {list.map((a) => <a key={a.slug} className="hp-row" href={`${base}/${a.slug}`}><b>{a.title}{a.status === "pending" ? " (not available yet)" : ""}</b><span>{a.summary}</span></a>)}
            </section>
          ) : null;
        })}
      </div>
    </>
  );
}
