import type { Metadata } from "next";
import { notFound } from "next/navigation";
import { HelpBody } from "@/components/cyrus/help/HelpBody";
import { helpArticle, helpArticles } from "@/lib/cyrus/help/articles.server";
import { helpGate } from "../_gate";

export const dynamic = "force-dynamic";

export async function generateMetadata({ params }: { params: Promise<{ slug: string }> }): Promise<Metadata> {
  const a = helpArticle((await params).slug);
  return a ? { title: `${a.title} · Cyrus Help`, description: a.summary } : { title: "Cyrus Help" };
}

export default async function HelpArticlePage({ params }: { params: Promise<{ slug: string }> }) {
  const { base } = await helpGate();
  const a = helpArticle((await params).slug);
  if (!a) notFound();
  const related = helpArticles().filter((x) => x.category === a.category && x.slug !== a.slug).slice(0, 4);
  return (
    <article className="hp-art">
      <nav className="hp-crumb" aria-label="Breadcrumb"><a href={base}>Help</a> / {a.category}</nav>
      <h1>{a.title}</h1>
      <p className="hp-lead">{a.summary}</p>
      {a.status === "pending" ? <p className="hp-pending" role="note">Part of this is not available yet. It is written here so you know what is coming.</p> : null}
      <HelpBody blocks={a.blocks} base={base} />
      {related.length ? (
        <section className="hp-more" aria-label="Related articles">
          <div className="cx-eyebrow">More in {a.category}</div>
          {related.map((r) => <a key={r.slug} href={`${base}/${r.slug}`}>{r.title}</a>)}
        </section>
      ) : null}
      <section className="hp-more" aria-label="Still stuck">
        <div className="cx-eyebrow">Still stuck?</div>
        <p className="cx-muted" style={{ margin: 0 }}>Open a Nxeon support ticket and tell us the project name. We can see your build details when you open it from the build page.</p>
      </section>
    </article>
  );
}
