// Cyrus help center (r50): the articles are real, linked, honest, and the renderer cannot emit raw markup.
import { describe, it } from "node:test";
import assert from "node:assert/strict";
import { readdirSync, readFileSync } from "node:fs";
import path from "node:path";
import { loadHelpArticles } from "../lib/cyrus/help/articles.server";
import { parseBlocks, parseInline, parseFrontmatter } from "../lib/cyrus/help/markdown";
import { HELP_CATEGORIES, searchHelp } from "../lib/cyrus/help/search";
import { helpPath } from "../lib/cyrus/help/paths";
import { cyrusHostRoute } from "../lib/cyrus/bridge/routing";
import { bridgeConfig } from "../lib/cyrus/bridge/config";

const DIR = path.resolve(__dirname, "..", "content", "cyrus", "help");
const articles = loadHelpArticles(DIR);

describe("help center content", () => {
  it("has about 25 articles with complete front matter", () => {
    assert.ok(articles.length >= 25, `only ${articles.length} articles`);
    for (const a of articles) {
      assert.ok(a.title && a.summary, a.slug);
      assert.ok((HELP_CATEGORIES as readonly string[]).includes(a.category), `${a.slug}: category ${a.category}`);
      assert.ok(a.order < 999, `${a.slug}: needs an order`);
      assert.ok(a.blocks.length >= 3, a.slug);
    }
    assert.equal(new Set(articles.map((a) => a.order)).size, articles.length, "orders are unique");
  });
  it("covers every topic the polish brief names", () => {
    const need = ["getting-started", "writing-a-good-prompt", "studios-overview", "texture-studio", "sound-studio", "model-studio", "motion-and-effects", "config-studio", "designers", "libraries",
      "plans-and-tokens", "token-rollover-and-free-tokens", "how-spend-is-shown", "refunds-and-failed-builds", "connect-nxeon", "server-grants", "installing-and-rolling-back", "test-flight",
      "mod-packs-and-modules", "troubleshooting", "safety-and-licensing", "reporting-and-takedowns", "privacy-and-your-data", "api-keys-and-the-api"];
    const have = new Set(articles.map((a) => a.slug));
    assert.deepEqual(need.filter((s) => !have.has(s)), []);
  });
  it("every help: link resolves, every other link is safe", () => {
    const slugs = new Set(articles.map((a) => a.slug));
    for (const a of articles) {
      for (const m of a.raw.matchAll(/\]\(help:([^)]+)\)/g)) assert.ok(slugs.has(m[1]), `${a.slug} -> ${m[1]}`);
      for (const m of a.raw.matchAll(/\]\(([^)]+)\)/g)) assert.ok(/^(help:|https?:|\/|#)/.test(m[1]), `${a.slug}: odd link ${m[1]}`);
    }
  });
  it("modules are marked pending (r45 is not merged)", () => {
    assert.equal(articles.find((a) => a.slug === "mod-packs-and-modules")?.status, "pending");
  });
  it("is honest: no model family names, no provider talk, no prices or token amounts, no emoji or dashes as punctuation", () => {
    for (const f of readdirSync(DIR)) {
      const t = readFileSync(path.join(DIR, f), "utf8");
      assert.doesNotMatch(t, /\b(claude|haiku|sonnet|opus|anthropic|gpt|openai)\b/i, f);
      assert.doesNotMatch(t, /\bprovider\b/i, f);
      assert.doesNotMatch(t, /[$€£]\s?\d/, `${f}: a price`);
      assert.doesNotMatch(t, /\b\d[\d,]*\s*(tokens|free tokens)\b/i, `${f}: a token amount`);
      assert.doesNotMatch(t, /[\u{1F300}-\u{1FAFF}☀-➿]|—/u, `${f}: emoji or em dash`);
    }
  });
  it("never claims another game is available (Minecraft only)", () => {
    const g = articles.find((a) => a.slug === "games-and-versions")!;
    assert.match(g.text, /coming soon/i);
    assert.match(g.text, /Hytale and FiveM\/RedM are on hold/);
  });
});

describe("help search", () => {
  const idx = articles.map(({ blocks: _b, raw: _r, ...e }) => e);
  it("finds the right article first", () => {
    assert.equal(searchHelp(idx, "rollover")[0]?.slug, "token-rollover-and-free-tokens");
    assert.equal(searchHelp(idx, "boot-tested")[0]?.slug, "test-flight");
    assert.equal(searchHelp(idx, "api key")[0]?.slug, "api-keys-and-the-api");
    assert.equal(searchHelp(idx, "takedown")[0]?.slug, "reporting-and-takedowns");
    assert.equal(searchHelp(idx, "revoke")[0]?.slug, "server-grants");
  });
  it("needs every word, and empty or nonsense finds nothing", () => {
    assert.deepEqual(searchHelp(idx, ""), []);
    assert.deepEqual(searchHelp(idx, "zzqxv"), []);
    assert.deepEqual(searchHelp(idx, "rollover zzqxv"), []);
  });
});

describe("help markdown renderer is safe", () => {
  it("never produces raw HTML nodes; unsafe link targets become plain text", () => {
    const i = parseInline("[x](javascript:alert(1)) <script>alert(1)</script> [ok](https://nxeon.cloud) [h](help:test-flight)");
    const flat = JSON.stringify(i);
    assert.doesNotMatch(flat, /"href":"javascript/);
    assert.ok(i.some((n) => n.t === "link" && n.href === "https://nxeon.cloud"));
    assert.ok(i.some((n) => n.t === "help" && n.slug === "test-flight"));
    assert.ok(i.some((n) => n.t === "text" && n.v.includes("<script>")), "kept as text, React escapes it");
    assert.ok(!i.some((n) => n.t === "link" && /^\/\//.test(n.href)));
  });
  it("parses blocks and front matter", () => {
    const { meta, body } = parseFrontmatter("---\ntitle: T\norder: 3\n---\n## A\n\ntext **b** `c`\n\n- one\n- two\n\n1. x\n\n| a | b |\n|---|---|\n| 1 | 2 |\n\n```\ncode\n```\n");
    assert.equal(meta.title, "T");
    const t = parseBlocks(body).map((b) => b.t);
    assert.deepEqual(t, ["h", "p", "ul", "ol", "table", "code"]);
  });
});

describe("help routing", () => {
  const cfg = bridgeConfig({ CYRUS_DOMAIN_MODE: "1", APP_URL: "https://nxeon.cloud" });
  const r = (pathname: string, method = "GET") => cyrusHostRoute({ pathname, search: "", method, cfg });
  it("cyrus.my /help[/slug] rewrites to the route group; nothing else", () => {
    assert.deepEqual(r("/help"), { kind: "rewrite", pathname: "/cyrus-help" });
    assert.deepEqual(r("/help/test-flight"), { kind: "rewrite", pathname: "/cyrus-help/test-flight" });
    assert.deepEqual(r("/help/a/b"), { kind: "notfound" });
    assert.deepEqual(r("/help/..%2fx"), { kind: "notfound" });
    assert.deepEqual(r("/help", "POST"), { kind: "notfound" });
    assert.equal(helpPath("/helpful"), null);
  });
});
