// Cyrus customer-app copy (r50): the tour points at real anchors, and the words follow the rules (plain, no jargon,
// no model names, no owner numbers, a next step in every failure).
import { describe, it } from "node:test";
import assert from "node:assert/strict";
import { readFileSync } from "node:fs";
import path from "node:path";
import { EMPTY, MSG, TIPS, TOUR_STEPS } from "../lib/cyrus/content/copy";

const ROOT = path.resolve(__dirname, "..");
const read = (p: string) => readFileSync(path.join(ROOT, p), "utf8");
const APP_SRC = ["app/dashboard/cyrus/app/page.tsx", "components/cyrus/app/AppNav.tsx", "components/cyrus/app/ui.tsx"].map(read).join("\n");

describe("onboarding tour", () => {
  it("covers connect a server, first mod, watch it build, install", () => {
    assert.deepEqual(TOUR_STEPS.slice(0, 4).map((s) => s.id), ["servers", "new", "projects", "builds"]);
    assert.match(TOUR_STEPS[0].title, /server/i);
    assert.match(TOUR_STEPS[1].title, /first mod/i);
    assert.match(TOUR_STEPS[2].title, /build/i);
    assert.match(TOUR_STEPS[3].title, /install/i);
  });
  it("every step points at an anchor that exists in the app", () => {
    for (const s of TOUR_STEPS) {
      const name = /data-tour="([^"]+)"/.exec(s.sel)![1];
      const ok = APP_SRC.includes(`data-tour="${name}"`) || APP_SRC.includes(`tour="${name}"`) || (name.startsWith("nav-") && APP_SRC.includes("data-tour={`nav-${k}`}"));
      assert.ok(ok, `no anchor for ${s.id} (${name})`);
    }
  });
});

describe("copy rules", () => {
  const texts = (): string[] => [
    ...TOUR_STEPS.flatMap((s) => [s.title, s.body]), ...Object.values(EMPTY), ...Object.values(TIPS),
    ...Object.values(MSG).map((m) => (typeof m === "function" ? m(500) : m)),
  ];
  it("no jargon, model names, owner numbers, emoji or em dashes", () => {
    for (const t of texts()) {
      assert.doesNotMatch(t, /\b(claude|haiku|sonnet|opus|anthropic|idempot|journal|preview rules|metered|reserve table|engine revision|switched on)\b/i, t);
      assert.doesNotMatch(t, /[$€£]\s?\d/, t);
      assert.doesNotMatch(t, /[\u{1F300}-\u{1FAFF}☀-➿]|—/u, t);
      assert.ok(t.length <= 260, `too long: ${t}`);
    }
  });
  it("every failure says what happened to the user's stuff and what to do next", () => {
    for (const [k, m] of Object.entries(MSG)) {
      const t = typeof m === "function" ? m(500) : m;
      if (k === "disconnectConfirm") continue; // a confirmation, not a failure
      assert.match(t, /(try again|check|refresh|see plans|get tokens|tell support|download|choose|nothing to)/i, `${k}: no next step`);
    }
    assert.match(MSG.networkBuild, /nothing was charged/i);
    assert.match(MSG.buildStart(502), /nothing was charged/i);
    assert.match(MSG.installFailed(500), /server was not changed/i);
  });
  it("never blames the customer", () => {
    for (const t of texts()) assert.doesNotMatch(t, /\byou (failed|forgot|must have|should have|did something wrong|entered an invalid)\b/i, t);
  });
});
