// Cyrus plans and pricing copy (r50). PURE, client-safe. The landing's voice: short, concrete, no hype.
// RULES: no prices, no token amounts, no invented stats or testimonials. Everything the owner still has to decide is a
// PLACEHOLDER (see PLACEHOLDERS): the page renders it as a visible, dashed "to be announced" slot so nobody mistakes it
// for a real figure. When the owner decides, pass real values through `PlanValues` (from settings) and nothing else
// changes. Token rules are the product rules from the separation/token work (rollover while subscribed, free tokens
// with servers and renewals); their exact amounts are configurable and never appear in copy.
import type { CyrusModelId } from "../models";

export type PlanId = "free" | CyrusModelId;
export type PlanCopy = {
  id: PlanId; name: string; tier: string; lead: string;
  /** What is included. */
  has: readonly string[];
  /** What is not (shown dimmed). */
  not: readonly string[];
  cta: string;
};

export const PLANS_HEADLINE = { h: "Three tiers.", em: "Pick your power.", sub: "Cyrus builds Minecraft mods today. Every plan installs to your Nxeon servers or downloads as a jar." } as const;

export const PLANS: readonly PlanCopy[] = [
  { id: "katara", name: "Katara", tier: "Tier I", lead: "Code mods from a prompt.",
    has: ["Plan, code, compile, install", "Config sliders", "Install to your Nxeon servers", "Unused tokens roll over while subscribed"],
    not: ["Studios not included"], cta: "Start with Katara" },
  { id: "saka", name: "Saka", tier: "Tier II", lead: "Everything in Katara, with sound.",
    has: ["Everything in Katara", "Sound Studio", "Unused tokens roll over while subscribed"],
    not: ["Texture and 3D studios in Yakko"], cta: "Start with Saka" },
  { id: "yakko", name: "Yakko", tier: "Tier III", lead: "Every model, every studio.",
    has: ["All models", "Texture, Sound and 3D Model studios", "Asset libraries", "Unused tokens roll over while subscribed"],
    not: [], cta: "Start with Yakko" },
] as const;

export const FREE_PLAN = { name: "Free", lead: "Try Cyrus at no cost, with limits.", has: ["A starter allowance to try a build", "Download or install what you build"], not: ["Studios need a paid plan"], cta: "Try it free" } as const;

/** The token rules, in the exact words the landing and the pricing page use. */
export const TOKEN_RULES = {
  rollover: "Unused tokens roll over every month for as long as your plan stays active.",
  freeWithServers: "Every paid Nxeon game server you deploy comes with free Cyrus tokens, plus more on each renewal.",
  lapse: "Cancel and your plan tokens pause for a grace period: resubscribe in time and they're yours again.",
  neverLocked: "Installing, keeping, rebuilding unchanged and exporting a mod never need a plan or tokens.",
  estimate: "You always see an estimate before a build. It spends only what it uses, and a failed build gives its tokens back.",
} as const;

export const FAQ: readonly { q: string; a: string }[] = [
  { q: "What is a token?", a: "A unit of AI work. A bigger mod costs more than a small one. You see the estimate before you build, and the final amount when it ends." },
  { q: "What if I run out?", a: "Top up, change plan, or wait for next month's tokens. Anything you already built keeps working and can still be installed." },
  { q: "What do I lose if I move to a lower plan?", a: "Nothing you made. A lower plan only limits what you can create or change in the studios from then on." },
  { q: "How do the free server tokens work?", a: "Deploy a paid Nxeon game server for a game Cyrus builds for and you get free Cyrus tokens, with more on each renewal. Your balance shows where each batch came from. The amounts are set by Nxeon and can change." },
  { q: "Which games are included?", a: "Minecraft. Every other game is coming soon, and nothing is sold for a game that cannot be built yet." },
  { q: "Are the models different?", a: "Yes. Katara is fast and suits simple mods. Saka is balanced and suits most mods. Yakko is the strongest and suits big systems like bosses and quests." },
  { q: "Can I cancel?", a: "Yes, any time from Nxeon billing. See the token rules above for what happens to unused plan tokens." },
  { q: "Where do I ask about a charge or a refund?", a: "Open a Nxeon support ticket. Plans, top-ups and invoices are handled by Nxeon billing." },
];

/** Everything still to be decided by the owner. These render as visible placeholders, never as numbers. */
export const PLACEHOLDERS = [
  { key: "price.katara", label: "Katara monthly price" },
  { key: "price.saka", label: "Saka monthly price" },
  { key: "price.yakko", label: "Yakko monthly price" },
  { key: "tokens.katara", label: "Katara tokens per month" },
  { key: "tokens.saka", label: "Saka tokens per month" },
  { key: "tokens.yakko", label: "Yakko tokens per month" },
  { key: "free.allowance", label: "Free plan starter allowance" },
  { key: "server.grant", label: "Free tokens per paid server, and per renewal (and any per-server cap)" },
  { key: "rollover.cap", label: "Rollover cap, if any" },
  { key: "lapse.grace", label: "Grace period length after a plan lapses" },
  { key: "refund.policy", label: "Refund policy wording" },
] as const;
export type PlaceholderKey = (typeof PLACEHOLDERS)[number]["key"];

/** Real values, once the owner decides. Missing = the page shows the placeholder. */
export type PlanValues = Partial<Record<PlaceholderKey, string>>;
export const placeholderText = (key: PlaceholderKey, v: PlanValues = {}) => v[key] ?? null;
