  freeWithServers: "Every paid Nxeon game server you deploy comes with free Cyrus tokens, plus more on each renewal.",
  lapse: "Cancel and your plan tokens pause for a grace period: resubscribe in time and they're yours again.",
  neverLocked: "Installing, keeping, rebuilding unchanged and exporting a mod never need a plan or tokens.",
  estimate: "You always see an estimate before a build. It spends only what it uses, and a failed build gives its tokens back.",
} as const;

export const FAQ: readonly { q: string; a: string }[] = [
  { q: "What is a token?", a: "A unit of AI work. A bigger mod costs more than a small one. You see the estimate before you build, and the final amount when it ends." },
  { q: "What if I run out?", a: "Top up, change plan, or wait for next month's tokens. Anything you already built keeps working and can still be installed." },
