  { q: "How do the free server tokens work?", a: "Deploy a paid Nxeon game server for a game Cyrus builds for and you get free Cyrus tokens, with more on each renewal. Your balance shows where each batch came from. The amounts are set by Nxeon and can change." },
  { q: "Which games are included?", a: "Minecraft. Every other game is coming soon, and nothing is sold for a game that cannot be built yet." },
  { q: "Are the models different?", a: "Yes. Katara is fast and suits simple mods. Saka is balanced and suits most mods. Yakko is the strongest and suits big systems like bosses and quests." },
  { q: "Can I cancel?", a: "Yes, any time from Nxeon billing. See the token rules above for what happens to unused plan tokens." },
  { q: "Where do I ask about a charge or a refund?", a: "Open a Nxeon support ticket. Plans, top-ups and invoices are handled by Nxeon billing." },
];

/** Everything still to be decided by the owner. These render as visible placeholders, never as numbers. */
export const PLACEHOLDERS = [
  { key: "price.katara", label: "Katara monthly price" },
  { key: "price.saka", label: "Saka monthly price" },
  { key: "price.yakko", label: "Yakko monthly price" },
  { key: "tokens.katara", label: "Katara tokens per month" },
  { key: "tokens.saka", label: "Saka tokens per month" },
  { key: "tokens.yakko", label: "Yakko tokens per month" },
  { key: "free.allowance", label: "Free plan starter allowance" },
