import type { Metadata } from "next";
import { FAQ, FREE_PLAN, PLANS, PLANS_HEADLINE, TOKEN_RULES, placeholderText, type PlanValues } from "@/lib/cyrus/content/plans";
import { helpGate } from "../_gate";

export const dynamic = "force-dynamic";
export const metadata: Metadata = { title: "Plans · Cyrus", description: "Katara, Saka and Yakko: what each plan includes and how Cyrus tokens work." };

/** Real values come from settings once the owner decides. Until then every price and amount is a visible placeholder. */
const VALUES: PlanValues = {};

function Slot({ k, what }: { k: Parameters<typeof placeholderText>[0]; what: string }) {
  const v = placeholderText(k, VALUES);
  return v ? <b>{v}</b> : <span className="pl-ph" data-placeholder={k} title="Not decided yet">{what} to be announced</span>;
}

export default async function PlansPage() {
  const { onCyrus } = await helpGate();
  const start = onCyrus ? "/new" : "/dashboard/cyrus/app/new";
  return (
    <>
      <div className="hp-hero">
        <div className="cx-eyebrow">Plans</div>
        <h1>{PLANS_HEADLINE.h} <span className="cx-grad">{PLANS_HEADLINE.em}</span></h1>
        <p className="cx-sub">{PLANS_HEADLINE.sub}</p>
      </div>
      <div className="pl-grid">
        {PLANS.map((p) => (
          <section key={p.id} className="cx-card pl-card" aria-label={p.name}>
            <div className="cx-eyebrow">{p.tier}</div>
            <h2>{p.name}</h2>
            <p className="pl-lead">{p.lead}</p>
            <p className="pl-price"><Slot k={`price.${p.id as "katara" | "saka" | "yakko"}`} what="Price" /></p>
            <p className="cx-faint pl-tok"><Slot k={`tokens.${p.id as "katara" | "saka" | "yakko"}`} what="Monthly tokens" /></p>
            <ul>
              {p.has.map((x) => <li key={x}>{x}</li>)}
              {p.not.map((x) => <li key={x} className="pl-dim">{x}</li>)}
            </ul>
            <a className={`cx-btn ${p.id === "yakko" ? "cx-btn-energy" : ""}`} href={start}>{p.cta}</a>
          </section>
        ))}
      </div>
      <div className="cx-note pl-free"><b>{FREE_PLAN.name}</b> {FREE_PLAN.lead} <Slot k="free.allowance" what="Starter allowance" />. {FREE_PLAN.not[0]}. <a href={start} style={{ textDecoration: "underline" }}>{FREE_PLAN.cta}</a></div>

      <section className="pl-rules" aria-label="How tokens work">
        <h2>How tokens work</h2>
        <ul>
          <li>{TOKEN_RULES.rollover}</li>
          <li>{TOKEN_RULES.freeWithServers} <Slot k="server.grant" what="Amount" /></li>
          <li>{TOKEN_RULES.lapse} <Slot k="lapse.grace" what="Grace period" /></li>
          <li>{TOKEN_RULES.estimate}</li>
          <li>{TOKEN_RULES.neverLocked}</li>
        </ul>
      </section>

      <section className="pl-faq" aria-label="Questions">
        <h2>Questions</h2>
        {FAQ.map((f) => <details key={f.q}><summary>{f.q}</summary><p>{f.a}</p></details>)}
      </section>
    </>
  );
}
