// Cyrus support content (r50): the macros, email review, status page copy and launch announcement are complete and
// follow the house rules (speak as Nxeon, no model names, no invented figures, honest about games).
import { describe, it } from "node:test";
import assert from "node:assert/strict";
import { readFileSync } from "node:fs";
import path from "node:path";
import { NOTIFY_EVENTS } from "../lib/cyrus/notify/events";
import { renderNotification, SAMPLE_DATA } from "../lib/cyrus/notify/templates";

const ROOT = path.resolve(__dirname, "..");
const doc = (n: string) => readFileSync(path.join(ROOT, "docs/cyrus/support", n), "utf8");
const NAMES = ["macros.md", "email-templates.md", "status-page.md", "whats-new.md", "copy-review.md"];

describe("support content", () => {
  it("has exactly 20 numbered macros, each with a Look-at line, a reply and a sign-off", () => {
    const t = doc("macros.md");
    const parts = t.split(/\n(?=## \d+\. )/).slice(1);
    assert.equal(parts.length, 20);
    parts.forEach((p, i) => {
      assert.match(p, new RegExp(`^## ${i + 1}\\. `), `macro ${i + 1} out of order`);
      assert.match(p, /\*\*Look at:\*\*/, `macro ${i + 1}`);
      assert.match(p, /\n> Hi \{\{name\}\},/, `macro ${i + 1}`);
      assert.match(p, /Nxeon Support/, `macro ${i + 1}`);
    });
  });
  it("covers the cases the brief names", () => {
    const t = doc("macros.md").toLowerCase();
    for (const k of ["build failed", "tokens", "refund", "server", "takedown", "copyright", "counter-notice", "outdated", "rollback", "test flight", "api key", "sign in", "another game"]) assert.ok(t.includes(k), k);
  });
  it("legal macros are flagged for approval; replies are drafts only", () => {
    const t = doc("macros.md");
    assert.equal((t.match(/Legal wording to be approved/g) ?? []).length, 3);
    assert.match(t, /only send after a person has approved/i);
  });
  it("house rules: no outside-provider talk, no model names, no prices or token figures, no emoji or em dash", () => {
    for (const n of NAMES) {
      const t = doc(n);
      assert.doesNotMatch(t, /\bprovider\b/i, n);
      assert.doesNotMatch(t, /\b(claude|haiku|sonnet|opus|anthropic|openai)\b/i, `${n}: model name`);
      assert.doesNotMatch(t.replace(/\{\{[^}]*\}\}/g, ""), /[$€£]\s?\d/, `${n}: price`);
      assert.doesNotMatch(t, /[\u{1F300}-\u{1FAFF}☀-➿]|—/u, `${n}: emoji or em dash`);
    }
  });
  it("the launch announcement is honest: Minecraft first, no modules, limits stated", () => {
    const t = doc("whats-new.md");
    assert.match(t, /Other games are coming soon/);
    assert.match(t, /not in a real game client yet/);
    assert.match(t, /Modules .*\*\*Not available/);
    assert.doesNotMatch(t, /\b(admin|ops|staff|dashboard for staff)\b.*\b(new|added)\b/i);
  });
  it("status page has components, stages and the standing line about installed mods", () => {
    const t = doc("status-page.md");
    for (const k of ["Builds", "Test Flight", "Installs", "Tokens and plans", "Investigating", "Identified", "Monitoring", "Resolved", "keep running"]) assert.ok(t.includes(k), k);
    assert.equal((t.match(/^\*\*\d+\. /gm) ?? []).length, 10);
  });
});

describe("reviewed email copy still renders for every event", () => {
  it("renders, escapes, and keeps the honest lines", () => {
    for (const e of NOTIFY_EVENTS) {
      const r = renderNotification(e.id, SAMPLE_DATA[e.id], { appBase: "https://cyrus.my", prefsUrl: "https://cyrus.my/dashboard/cyrus/notifications" });
      assert.ok(r.subject && r.html.includes("<table") && r.text.includes("Cyrus, a Nxeon product."), e.id);
    }
    const fail = renderNotification("install.result", { name: "X", ok: false, reason: "server stopped" }, { appBase: "https://cyrus.my", prefsUrl: "https://cyrus.my/p" });
    assert.match(fail.body, /undid its changes where it could/);
    assert.doesNotMatch(fail.body, /was rolled back/);
    const tk = renderNotification("takedown", { name: "X", what: "A library asset", reason: "copyright notice" }, { appBase: "https://cyrus.my", prefsUrl: "https://cyrus.my/p" });
    assert.match(tk.body, /keep their own copy/);
    const tk2 = renderNotification("takedown", { name: "X", counterNotice: true }, { appBase: "https://cyrus.my", prefsUrl: "https://cyrus.my/p" });
    assert.match(tk2.body, /keep their own copy/);
    assert.match(tk2.body, /counter-notice/);
  });
});
