  const page = await ctx.newPage();
  await page.addInitScript(([t]) => { try { localStorage.setItem("nx-theme", t); localStorage.setItem("cyrus-app-tour-v1", "done"); localStorage.setItem("nx-tour-dismissed", "1"); } catch {} }, [theme]);
  const errs = [];
  page.on("pageerror", (e) => errs.push(String(e).slice(0, 300)));
