  const overflow = await page.evaluate(() => document.documentElement.scrollWidth - window.innerWidth).catch(() => 0);
  await page.screenshot({ path: `${OUT}/${name}.png`, fullPage: true, timeout: 120000 }).catch((e) => errs.push("shot " + String(e).slice(0, 120)));
  console.log(`${name}.png`, res ? res.status() : "-", overflow > 1 ? `OVERFLOW ${overflow}px` : "", errs.length ? "ERR " + errs.join(" | ").slice(0, 600) : "");
  await ctx.close();
}
await shot("help-home-dark", "/cyrus-help");
await shot("help-home-light", "/cyrus-help", { theme: "light" });
await shot("help-home-phone", "/cyrus-help", { view: "phone" });
await shot("help-search-dark", "/cyrus-help?q=rollover");
await shot("help-article-dark", "/cyrus-help/test-flight");
await shot("help-article-pending-phone", "/cyrus-help/mod-packs-and-modules", { view: "phone" });
await shot("plans-dark", "/cyrus-help/plans");
await shot("plans-light", "/cyrus-help/plans", { theme: "light" });
await shot("plans-phone", "/cyrus-help/plans", { view: "phone" });
if (tok) {
  await shot("new-templates-dark", "/dashboard/cyrus/app/new", { signed: true, wait: ".cx-page", act: async (p) => { await p.click("text=Ember wand"); await p.waitForTimeout(500); } });
  await shot("new-templates-phone", "/dashboard/cyrus/app/new", { signed: true, view: "phone", wait: ".cx-page" });
}
await browser.close();
EOF
